import ast
import json
from collections import Counter
def task_func(file_pointer):
    data = json.load(file_pointer)
    results = []
    for item in data:
        try:
            d = ast.literal_eval(item) if isinstance(item, str) else item
            if isinstance(d, dict):
                results.append(d)
        except (ValueError, SyntaxError):
            continue
    key_counter = Counter()
    for d in results:
        key_counter.update(d.keys())
    return key_counter
